struct Box { int weight; };
Box box{42};
auto& weight = std::invoke(&Box::weight, box);
weight = 50; // меняет box.weight

struct Scale {
  double operator()(int count) const;
};
using R = std::invoke_result_t<const Scale&, int>;
// Вызов const Scale с аргументом int допустим; R — double.
// Достаточно объявления operator(): для вычисления типа вызов не выполняется.
